create table public.procurement_orders(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, supplier_id uuid not null, order_number text not null, order_date date not null default current_date, status text not null default 'DRAFT' check(status in ('DRAFT','POSTED','SHIPPED','RECEIVED','REVERSED','CANCELLED')), external_order_number text, tracking_number text, notes text, created_by uuid default auth.uid(), posted_at timestamptz, received_at timestamptz, unique(workspace_id,id), unique(workspace_id,order_number), foreign key(workspace_id,supplier_id) references public.suppliers(workspace_id,id));
create table public.procurement_items(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, procurement_order_id uuid not null, sku_id uuid not null, qty integer not null check(qty>0), unit_cost_snapshot numeric(24,6) check(unit_cost_snapshot>=0), destination_type text not null check(destination_type in ('WAREHOUSE','CUSTOMER','SHOPEE_ORDER','RESELLER_ORDER','B2B_ORDER')), destination_reference_id uuid, inventory_location_id uuid, unique(workspace_id,id), check(destination_type<>'WAREHOUSE' or inventory_location_id is not null), foreign key(workspace_id,procurement_order_id) references public.procurement_orders(workspace_id,id), foreign key(workspace_id,sku_id) references public.skus(workspace_id,id), foreign key(workspace_id,inventory_location_id) references public.inventory_locations(workspace_id,id));
create table public.supplier_deposit_entries(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, supplier_id uuid not null, transaction_date date not null, entry_type text not null check(entry_type in ('OPENING','TOPUP','PURCHASE','REFUND','ADJUSTMENT_IN','ADJUSTMENT_OUT','REVERSAL')), amount numeric(24,6) not null check(amount<>0), reference_type text, reference_id uuid, notes text, status text not null default 'POSTED' check(status in ('DRAFT','POSTED','REVERSED','CANCELLED')), created_by uuid default auth.uid(), posted_at timestamptz default now(), reversed_entry_id uuid unique references public.supplier_deposit_entries, unique(workspace_id,id), foreign key(workspace_id,supplier_id) references public.suppliers(workspace_id,id), check((entry_type in ('OPENING','TOPUP','REFUND','ADJUSTMENT_IN') and amount>0) or (entry_type in ('PURCHASE','ADJUSTMENT_OUT') and amount<0) or entry_type='REVERSAL'));
create unique index one_procurement_deduction on public.supplier_deposit_entries(workspace_id,reference_type,reference_id) where entry_type='PURCHASE' and reference_type='procurement';
create table public.inventory_movements(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, sku_id uuid not null, location_id uuid not null, transaction_date date not null default current_date, qty_delta integer not null check(qty_delta<>0), movement_type text not null check(movement_type in ('OPENING_BALANCE','RESTOCK_RECEIVED','SHOPEE_SALE','WHATSAPP_SALE','B2B_SALE','RESELLER_SALE','MANUAL_SALE','OTHER_SALE','CUSTOMER_RETURN','DAMAGE','ADJUSTMENT_IN','ADJUSTMENT_OUT','REVERSAL')), unit_cost numeric(24,6) not null check(unit_cost>=0), source_type text, source_id uuid, notes text, created_by uuid default auth.uid(), posted_at timestamptz not null default now(), reversal_of uuid unique references public.inventory_movements, unique(workspace_id,id), foreign key(workspace_id,sku_id) references public.skus(workspace_id,id), foreign key(workspace_id,location_id) references public.inventory_locations(workspace_id,id));
